// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement"
// Changes: Drop incoming parameter values that cannot reach a read and compact
// all call sites.
#include "ir_free_helpers.h"
#include "optimizer_calls.h"

#include <string.h>

/**
 * @brief Determine whether the incoming parameter can reach a load before an
 * overwrite.
 *
 * @param fn Function whose incoming argument is inspected.
 * @param slot Parameter slot being tracked.
 * @param id Block to search.
 * @param[in,out] seen Visited blocks reached before an overwrite.
 * @return True if a path can read the incoming argument.
 */
// An overwrite kills the incoming argument on that path; only paths reaching a
// load need it.
static bool reaches_load(IrFunction* fn,
                         IrStackSlotId slot,
                         IrBlockId id,
                         bool* seen) {
  if (seen[id])
    return false;

  seen[id] = true;

  const IrBlock* block = &fn->blocks.data[id];

  for (size_t i = 0; i < block->instructions.count; i++) {
    const IrInstruction* inst = &block->instructions.data[i];

    if (inst->type == IR_INST_LOAD && inst->operands.load.source == slot)
      return true;

    if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
      return false;
  }

  const IrBlockTerminator* term = &block->terminator;
  if (term->type == IR_TERMINATOR_JUMP)
    return reaches_load(fn, slot, term->value.jump_target, seen);

  if (term->type == IR_TERMINATOR_CONDITIONAL)
    return reaches_load(fn, slot, term->value.conditional_target.true_target,
                        seen) ||
           reaches_load(fn, slot, term->value.conditional_target.false_target,
                        seen);

  return false;
}

/**
 * @brief Move the removed parameter to the local suffix and shift intervening
 * slot IDs.
 *
 * @param id Original stack slot ID.
 * @param removed Slot moved out of the parameter prefix.
 * @param last New ID of the former parameter.
 * @return Stack slot ID after the signature rewrite.
 */
static IrStackSlotId remap(IrStackSlotId id,
                           IrStackSlotId removed,
                           IrStackSlotId last) {
  if (id == removed)
    return last;

  return id > removed ? id - 1 : id;
}

/**
 * @brief Rewrite the function signature and every call site after dropping an
 * argument.
 *
 * @param program Program containing the callee and all its callers.
 * @param target Function whose signature is compacted.
 * @param removed Parameter position to remove.
 */
static void remove_parameter(IrProgram* program,
                             IrFunctionId target,
                             IrStackSlotId removed) {
  IrFunction* function = &program->functions.data[target];
  IrStackSlotId last = function->slots.count - 1;
  // Keep the slot as a local if the callee still uses it after assigning it.
  IrStackSlot previous = function->slots.data[removed];
  memmove(function->slots.data + removed, function->slots.data + removed + 1,
          (last - removed) * sizeof(previous));
  function->slots.data[last] = previous;
  function->parameter_count--;

  for (IrFunctionId fid = 0; fid < program->functions.count; fid++) {
    IrFunction* fn = &program->functions.data[fid];
    for (IrBlockId bid = 0; bid < fn->blocks.count; bid++) {
      IrInstructionArray* instructions = &fn->blocks.data[bid].instructions;
      for (size_t i = 0; i < instructions->count; i++) {
        IrInstruction* inst = &instructions->data[i];

        if (inst->type == IR_INST_CALL && inst->operands.call.id == target) {
          IrOperand* args = inst->operands.call.args;
          size_t end = --inst->operands.call.arg_count;

          // Only the argument operand is removed here. Dead-code cleanup
          // still decides whether evaluating its producer has effects.
          ir_free_operand(&args[removed]);
          memmove(args + removed, args + removed + 1,
                  (end - removed) * sizeof(*args));
        }

        if (fid == target && inst->type == IR_INST_LOAD)
          inst->operands.load.source =
              remap(inst->operands.load.source, removed, last);

        if (fid == target && inst->type == IR_INST_STORE)
          inst->operands.store.target =
              remap(inst->operands.store.target, removed, last);
      }
    }
  }
}

bool optimizer_remove_unused_parameters(Ctx* ctx) {
  bool changed = false;

  for (IrFunctionId fid = 0; fid < ctx->ir.functions.count; fid++) {
    if (fid == ctx->ir.entrypoint)
      continue;

    IrFunction* fn = &ctx->ir.functions.data[fid];
    // Work backward so removing one parameter does not renumber those still to
    // be examined.
    for (IrStackSlotId slot = fn->parameter_count; slot-- > 0;) {
      bool* seen = ctx->optimizer.blocks;
      memset(seen, 0, fn->blocks.count * sizeof(*seen));

      if (reaches_load(fn, slot, fn->entrypoint, seen))
        continue;

      remove_parameter(&ctx->ir, fid, slot);
      changed = true;
    }
  }

  return changed;
}
